import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { AccessApi } from '../core/access-api';
import { GradeView, YearDetail, YearSummary } from '../core/academic-api';
import { Shell } from '../shared/shell';
import { Icon } from '../shared/icon';

/**
 * Excel exports for official processes (MINEDUC/SIRE uploads, archives, board meetings): enrollment list, grade
 * board per period, yearly consolidated board and attendance summary. Files are generated by the server on demand.
 */
@Component({
  imports: [Shell, Icon, FormsModule],
  template: `
    <app-shell title="Reportes oficiales">
      <div class="page-heading">
        <div>
          <span class="eyebrow">REPORTES</span>
          <h1>Cuadros y consolidados</h1>
          <p>Descarga en Excel la información que piden los procesos oficiales. Revisa el formato exigido antes de subirla.</p>
        </div>
      </div>
      @if (error()) {
        <p class="feedback error-feedback" role="alert">{{ error() }}</p>
      }
      <section class="card directory-card">
        <div class="filters">
          <label class="select-field"
            ><span>Ciclo</span
            ><select name="year" [(ngModel)]="yearId" (ngModelChange)="loadYear()">
              @for (y of years(); track y.id) {
                <option [value]="y.id">{{ y.label }}</option>
              }
            </select></label
          >
          <label class="select-field"
            ><span>Grado</span
            ><select name="grade" [(ngModel)]="gradeId" (ngModelChange)="sectionId = ''">
              <option value="">Todos (solo nómina)</option>
              @for (g of grades(); track g.id) {
                <option [value]="g.id">{{ g.name }}</option>
              }
            </select></label
          >
          <label class="select-field"
            ><span>Sección</span
            ><select name="section" [(ngModel)]="sectionId" [disabled]="!gradeId">
              <option value="">Todas</option>
              @for (s of detail()?.sections ?? []; track s.id) {
                @if (s.gradeLevelId === gradeId) {
                  <option [value]="s.id">{{ s.name }}</option>
                }
              }
            </select></label
          >
          <label class="select-field"
            ><span>Período</span
            ><select name="period" [(ngModel)]="periodId">
              @for (p of detail()?.periods ?? []; track p.id) {
                <option [value]="p.id">{{ p.name }}</option>
              }
            </select></label
          >
        </div>
      </section>
      <div class="report-grid">
        <section class="card detail-card">
          <h2><app-icon name="users" /> Nómina de inscritos</h2>
          <p class="muted-copy">Código, nombres, fecha de nacimiento, grado, sección y estado de cada inscripción.</p>
          <a class="button outline" [href]="url('enrollments')" download><app-icon name="download" />Descargar Excel</a>
        </section>
        <section class="card detail-card">
          <h2><app-icon name="star" /> Cuadro del período</h2>
          <p class="muted-copy">Notas de cada estudiante por materia en el período elegido.</p>
          <a class="button outline" [class.disabled]="!gradeId || !periodId" [attr.href]="gradeId && periodId ? url('board') : null" download
            ><app-icon name="download" />Descargar Excel</a
          >
        </section>
        <section class="card detail-card">
          <h2><app-icon name="chart" /> Consolidado anual</h2>
          <p class="muted-copy">Todas las materias y períodos lado a lado, como fueron registrados (sin promedios).</p>
          <a class="button outline" [class.disabled]="!gradeId" [attr.href]="gradeId ? url('consolidated') : null" download
            ><app-icon name="download" />Descargar Excel</a
          >
        </section>
        <section class="card detail-card">
          <h2><app-icon name="calendar" /> Asistencia</h2>
          <p class="muted-copy">Días registrados, ausencias, tardanzas y porcentaje por estudiante en el ciclo.</p>
          <a class="button outline" [class.disabled]="!gradeId" [attr.href]="gradeId ? url('attendance') : null" download
            ><app-icon name="download" />Descargar Excel</a
          >
        </section>
      </div>
      @if (!gradeId) {
        <p class="muted-copy">Elige un grado para habilitar cuadros, consolidado y asistencia.</p>
      }
    </app-shell>
  `,
})
export class OfficialReports implements OnInit {
  private readonly api = inject(AccessApi);
  readonly years = signal<YearSummary[]>([]);
  readonly grades = signal<GradeView[]>([]);
  readonly detail = signal<YearDetail | null>(null);
  readonly error = signal('');
  yearId = '';
  gradeId = '';
  sectionId = '';
  periodId = '';

  async ngOnInit(): Promise<void> {
    try {
      const [years, grades] = await Promise.all([
        this.api.get<YearSummary[]>('/api/v1/academic/years'),
        this.api.get<GradeView[]>('/api/v1/academic/grades'),
      ]);
      this.years.set(years);
      this.grades.set(grades);
      this.yearId = (years.find((y) => y.isDefault) ?? years[0])?.id ?? '';
      if (this.yearId) await this.loadYear();
    } catch (error) {
      this.error.set(this.api.message(error));
    }
  }

  async loadYear(): Promise<void> {
    const detail = await this.api.get<YearDetail>(`/api/v1/academic/years/${this.yearId}`);
    this.detail.set(detail);
    this.sectionId = '';
    this.periodId = detail.periods[0]?.id ?? '';
  }

  url(kind: 'enrollments' | 'board' | 'consolidated' | 'attendance'): string {
    const q = new URLSearchParams();
    if (this.gradeId) q.set('gradeId', this.gradeId);
    if (this.sectionId) q.set('sectionId', this.sectionId);
    if (kind === 'board') q.set('periodId', this.periodId);
    return `/api/v1/years/${this.yearId}/reports/${kind}?${q}`;
  }
}
